function adicionar(tarefas, texto) {
  return [...tarefas, { texto, feita: false }];
}

function alternar(tarefas, indice) {
  return tarefas.map((t, i) => (i === indice ? { ...t, feita: !t.feita } : t));
}

function remover(tarefas, indice) {
  return tarefas.filter((_, i) => i !== indice);
}

